import sys

data = sys.stdin.read().split()
n = int(data[0])
r = [int(x) for x in data[1:1 + n]]

if n <= 18:
    best = None
    for mask in range(1 << n):
        ok = True
        for i in range(n - 1):
            if not (mask >> i) & 1 and not (mask >> (i + 1)) & 1:
                ok = False
                break
        if ok:
            tot = sum(r[i] for i in range(n) if (mask >> i) & 1)
            if best is None or tot > best:
                best = tot
    print(best)
else:
    sys.setrecursionlimit(10000)
    memo = {}

    def solve(i, prev_skipped):
        if i == n:
            return 0
        key = (i, prev_skipped)
        if key in memo:
            return memo[key]
        res = r[i] + solve(i + 1, False)
        if not prev_skipped:
            res = max(res, solve(i + 1, True))
        memo[key] = res
        return res

    print(solve(0, False))

