    for n in (2, 3, 4, 5, 6, 8, 10, 12, 14, 16):
        for _ in range(3):
            tests.append(fmt([rng.randint(-10, 10) for _ in range(n)]))
    for _ in range(4):
        tests.append(fmt([rng.randint(-1000, 1000) for _ in range(60)]))
    n = 10**5
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)]))
    tests.append(fmt([-rng.randint(1, 10**9) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(n)]))
    tests.append(fmt([(10**9 if i % 2 == 0 else -10**9) for i in range(n)]))
    return tests

